#!/usr/bin/env python3
"""Enrich a SIEM alert, then decide: auto-close, ask a human, or contain."""
import json, os, sys, time, requests

SIEM = "https://siem.example.com/api"
TOKEN = os.environ["SIEM_API_TOKEN"]          # never hard-code secrets
DRY_RUN = os.environ.get("DRY_RUN", "1") == "1"  # safe by default
MAX_ISOLATIONS_PER_HOUR = 3                   # guardrail against runaway loops

def api(method, path, **kw):
    r = requests.request(method, f"{SIEM}{path}", timeout=10,
                         headers={"Authorization": f"Bearer {TOKEN}"}, **kw)
    r.raise_for_status()
    return r.json()

def audit(alert_id, action, detail):
    # every decision is written down, including "did nothing"
    print(json.dumps({"ts": int(time.time()), "alert": alert_id,
                      "action": action, "detail": detail}))

def handle(alert_id):
    a = api("GET", f"/alerts/{alert_id}")
    if a.get("handled_by"):                    # idempotent: skip repeated runs
        return audit(alert_id, "skip", "already handled")
    host = a["host"]
    ctx = api("GET", f"/assets/{host}")        # owner, criticality, tags
    seen = api("GET", f"/alerts?host={host}&window=24h")["count"]

    if ctx["criticality"] == "high" or ctx["tags"].count("server"):
        return audit(alert_id, "escalate", f"{host} is critical, human decides")
    if seen >= 3 and a["severity"] >= 7:
        if DRY_RUN:
            return audit(alert_id, "would-isolate", host)
        api("POST", f"/hosts/{host}/isolate", json={"reason": alert_id})
        return audit(alert_id, "isolated", host)
    api("POST", f"/alerts/{alert_id}/close", json={"verdict": "benign-known"})
    audit(alert_id, "closed", "low severity, no repeats")

if __name__ == "__main__":
    handle(sys.argv[1])

